```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_k8s_pod_name, count(*) n, round(avg(value),2) av, min(value) mn, max(value) mx FROM abnormal_metrics WHERE metric IN ('k8s.container.ready','k8s.container.restarts') AND attr_k8s_pod_name LIKE 'search%' GROUP BY 1,2",
          "claim": "Search pod readiness stays 0 for the whole abnormal window while its restart counter climbs from 3 to 6."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_k8s_pod_name, count(*) n, min(value) mn, max(value) mx FROM normal_metrics WHERE metric IN ('k8s.container.ready','k8s.container.restarts') AND attr_k8s_pod_name LIKE 'search%' GROUP BY 1,2",
          "claim": "In the normal period the search pod was ready (1) with zero restarts throughout."
        },
        {
          "kind": "log",
          "sql": "SELECT regexp_extract(message, '\"reason\":\"([^\"]+)\"',1) reason, regexp_extract(message, '\"name\":\"(search[^\"]*)\"',1) obj, count(*) n FROM abnormal_logs GROUP BY 1,2",
          "claim": "Kubernetes events for the search pod show BackOff (19), Failed (6), Killing (1) and repeated Created/Pulled, a crash loop."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE span_name IN ('search.Search/Nearby','geo.Geo/Nearby','rate.Rate/GetRates') OR service_name='search' GROUP BY 1,2,3",
          "claim": "Search emits no server spans in the abnormal window; frontend's search.Search/Nearby client calls fail 673 of 678."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend' AND (span_name='HTTP /hotels' OR span_name='search.Search/Nearby') GROUP BY 1,2,3,4",
          "claim": "Frontend /hotels server spans return HTTP 500 in 673 of 678 requests, matching failed search.Search/Nearby calls; normal had zero errors."
        }
      ]
    }
  ]
}
```

